/* Command Center (@duwop/command-center): an add-on theme pack carrying three looks from Tyler's design suite,
   converted exactly from its hex tokens (tyler-design.css, 2026-10-11) to oklch.
     Redline        true black, gunmetal surfaces, signature red glow, JetBrains Mono
     Night Drive    blue on night indigo (the Tokyo Night palette by enkia, MIT licence)
     Event Horizon  near-black, steel blue, Space Grotesk; glow only on interaction
   All three are dark-only. Each theme has three blocks:
     1. --nh / --nc / --primary / --glow2, so the core shared rules still build a sane theme (and AMOLED works).
     2. .dark.dark.dark[...]: tokens that stay put with or without AMOLED. The tripled .dark is on purpose:
        four parts outrank the core shared rule (.dark[data-theme]:not(...), three parts) whichever CSS file
        loads first.
     3. .dark.dark[...]:not([data-amoled]): the exact surfaces (four parts), which AMOLED replaces with true black. */

/* ---- Redline ---- */
.dark[data-theme="redline"] {
  --nh: 268;
  --nc: 0.01;
  --primary: oklch(0.601 0.175 24);
  --glow2: oklch(0.52 0.139 24);
}
.dark.dark.dark[data-theme="redline"] {
  --foreground: oklch(0.946 0.003 265);
  --card-foreground: oklch(0.946 0.003 265);
  --popover-foreground: oklch(0.946 0.003 265);
  --secondary-foreground: oklch(0.946 0.003 265);
  --accent-foreground: oklch(0.946 0.003 265);
  --muted-foreground: oklch(0.579 0.015 267);
  --primary-foreground: oklch(0 0 0); /* black on the red: 4.9:1. White is 3.7:1 */
  --destructive: oklch(0.637 0.208 25);
  --border: oklch(1 0 0 / 7%);
  --input: oklch(1 0 0 / 10%);
  --ring: oklch(0.601 0.175 24);
  --glow: oklch(0.605 0.199 25);
  --radius: 0.75rem;
}
.dark.dark[data-theme="redline"]:not([data-amoled]) {
  --background: oklch(0 0 0);
  --card: oklch(0.086 0.006 285);
  --popover: oklch(0.173 0.009 264);
  --secondary: oklch(0.205 0.01 268);
  --muted: oklch(0.173 0.009 264);
  --accent: oklch(0.218 0.012 271);
}

/* ---- Night Drive: Tokyo Night palette by enkia (github.com/enkia/tokyo-night-vscode-theme, MIT) ---- */
.dark[data-theme="night-drive"] {
  --nh: 278;
  --nc: 0.025;
  --primary: oklch(0.719 0.132 264);
  --glow2: oklch(0.82 0.105 236);
}
.dark.dark.dark[data-theme="night-drive"] {
  --foreground: oklch(0.846 0.061 275);
  --card-foreground: oklch(0.846 0.061 275);
  --popover-foreground: oklch(0.846 0.061 275);
  --secondary-foreground: oklch(0.846 0.061 275);
  --accent-foreground: oklch(0.846 0.061 275);
  --muted-foreground: oklch(0.767 0.054 275);
  --primary-foreground: oklch(0.226 0.021 280);
  --destructive: oklch(0.723 0.159 10);
  --border: oklch(0.459 0.043 276);
  --input: oklch(0.459 0.043 276);
  --ring: oklch(0.719 0.132 264);
  --radius: 0.75rem;
}
.dark.dark[data-theme="night-drive"]:not([data-amoled]) {
  --background: oklch(0.226 0.021 280);
  --card: oklch(0.204 0.016 285);
  --popover: oklch(0.204 0.016 285);
  --secondary: oklch(0.306 0.037 273);
  --muted: oklch(0.261 0.034 274);
  --accent: oklch(0.306 0.037 273);
}

/* ---- Event Horizon: steel blue is the primary, ring and glow; the gunmetal panel is secondary / muted ---- */
.dark[data-theme="event-horizon"] {
  --nh: 253;
  --nc: 0.014;
  --primary: oklch(0.608 0.095 243);
  --glow2: oklch(0.586 0.132 278);
}
.dark.dark.dark[data-theme="event-horizon"] {
  --foreground: oklch(0.943 0.011 244);
  --card-foreground: oklch(0.943 0.011 244);
  --popover-foreground: oklch(0.943 0.011 244);
  --secondary-foreground: oklch(0.943 0.011 244);
  --accent-foreground: oklch(0.943 0.011 244);
  --primary-foreground: oklch(0.122 0.006 262);
  --muted-foreground: oklch(0.724 0.021 253);
  --destructive: oklch(0.634 0.116 13);
  --border: oklch(0.311 0.022 259);
  --input: oklch(0.311 0.022 259);
  --ring: oklch(0.608 0.095 243);
  --glow: oklch(0.608 0.095 243);
  --radius: 0.5rem;
}
.dark.dark[data-theme="event-horizon"]:not([data-amoled]) {
  --background: oklch(0.122 0.006 262);
  --card: oklch(0.211 0.014 253);
  --popover: oklch(0.211 0.014 253);
  --secondary: oklch(0.22 0.012 254);
  --muted: oklch(0.22 0.012 254);
  --accent: oklch(0.266 0.016 252);
}

// Command Center (@duwop/command-center): the theme entries for command-center.css. All dark-only.
// Add them in lib/duwop-config.ts: import { commandCenter } from "./command-center"; ... extraThemes: commandCenter.

import type { Theme } from "./theme";

export const commandCenter: Theme[] = [
  {
    id: "redline",
    name: "Redline",
    note: "True black, gunmetal and a red glow behind every card.",
    dark: true,
    font: "jetbrains",
    effects: ["underglow", "ambient"],
  },
  {
    id: "night-drive",
    name: "Night Drive",
    note: "Blue on night indigo (the Tokyo Night palette by enkia, MIT).",
    dark: true,
    font: "jetbrains",
    effects: ["underglow"],
  },
  {
    id: "event-horizon",
    name: "Event Horizon",
    note: "Near-black and steel blue. Glows only when you point at it.",
    dark: true,
    font: "spacegrotesk",
    effects: ["underglow"],
  },
];
